{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95ms FROM abnormal_traces WHERE service_name='ts-route-service' AND attr_span_kind='Client' AND span_name LIKE 'SELECT ts.route%' GROUP BY 1 ORDER BY 1", "claim": "In the incident, ts-route-service's SELECT ts.route_distances/route_stations DB calls have p95 around 430 ms, versus about 0.1 ms in normal."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95ms FROM normal_traces WHERE service_name='ts-route-service' AND attr_span_kind='Client' AND span_name LIKE 'SELECT ts.route%' GROUP BY 1 ORDER BY 1", "claim": "Normal-period route-service DB SELECT spans on ts.route_distances and ts.route_stations finish in about 0.1 ms at p95."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95ms FROM abnormal_traces WHERE service_name='ts-route-service' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 1,2", "claim": "route-service GET /routes server spans reach p95 of about 56 s with 14 errors; the route-by-id endpoint is slow too."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),2) avg_v, round(max(value),2) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-route-service%' AND metric IN ('container.cpu.usage','container.memory.rss') GROUP BY 1", "claim": "route-service pod CPU and memory stay low in the incident window, so the slowdown is not resource saturation in the pod."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name callee, p.service_name caller, count(*) n, round(quantile_cont(p.duration/1e6,0.95),1) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-service' AND c.attr_span_kind='Server' AND p.service_name='ts-ui-dashboard' GROUP BY 1,2", "claim": "ts-ui-dashboard's client calls into route-service are slow; the user-facing /routes requests take about 20 s."}
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-travel-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration/1e6,0.95),1) callee_srv_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-service' AND p.service_name='ts-travel-service' GROUP BY 1,2", "claim": "ts-travel-service calls into route-service; those calls take about 1 s at p95 in the incident."}
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration/1e6,0.95),1) callee_srv_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-travel-service' AND p.service_name='ts-admin-travel-service' GROUP BY 1,2", "claim": "ts-admin-travel-service calls ts-travel-service, whose admin_trip server span takes about 5.9 s at p95 in the incident."}
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, round(quantile_cont(duration/1e6,0.95),1) p95ms FROM abnormal_traces WHERE service_name='ts-admin-travel-service' AND attr_span_kind='Server' GROUP BY 1,2,3", "claim": "ts-admin-travel-service's admin travel GET server spans reach about 12 s at p95, and ui-dashboard calls it."}
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-travel2-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration/1e6,0.95),1) callee_srv_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-service' AND p.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "ts-travel2-service calls ts-route-service, and those calls take about 2.1 s at p95 in the incident."}
      ]
    }
  ]
}
